insert into articles (id, lang, region, category, title, body, source) values
  ('suppliers', 'vi', null, 'finance', 'Mua vật liệu và công nợ nhà cung cấp', 'Bộ phận tài chính ghi chứng từ mua vật liệu của nhà cung cấp gồm tên vật liệu, ngày nhập và số tiền. Công nợ nhà cung cấp bằng tổng tiền mua vật liệu trừ tổng tiền đã trả. Khi trả tiền, tài chính ghi lần trả tiền nhà cung cấp; số tiền trả không được lớn hơn số còn nợ. Chỉ tài chính và quản trị được ghi chứng từ; ban điều hành được xem số liệu tài chính.', 'finance R103 R104'),
  ('suppliers', 'en', null, 'finance', 'Material purchases and supplier balances', 'Finance records material purchase vouchers from suppliers with the material name, delivery date and amount. The supplier balance is the total of material purchases minus the total already paid. When paying, finance records a supplier payment; a payment cannot be larger than the amount still owed. Only finance and admins may record vouchers; executives may view the finance figures.', 'finance R103 R104'),
  ('month-close', 'vi', null, 'finance', 'Chốt sổ tháng', 'Tài chính chốt sổ cho một tháng đã kết thúc; tháng chưa hết thì không chốt được. Số liệu chốt sổ được gửi lên Hub để làm báo cáo tập đoàn. Tháng đã chốt sổ thì không nhập thêm chứng từ, kể cả doanh thu nghiệm thu dự án. Chỉ tài chính và quản trị được chốt sổ.', 'finance R62'),
  ('month-close', 'en', null, 'finance', 'Month-end close', 'Finance closes the books for a month that has ended; a month that is not over cannot be closed. The closing figures are sent to the Hub for the group report. A closed month accepts no more vouchers, including project acceptance revenue. Only finance and admins may close a month.', 'finance R62'),
  ('acceptance', 'vi', null, 'projects', 'Nghiệm thu dự án và doanh thu', 'Khi dự án hoàn thành, tài chính, quản trị hoặc ban điều hành bấm nghiệm thu dự án. Service dự án gọi service tài chính để ghi doanh thu nghiệm thu, tỷ giá lấy theo ngày nghiệm thu, rồi đánh dấu dự án đã nghiệm thu. Nếu tháng nghiệm thu đã chốt sổ thì không nghiệm thu được và app báo đúng lý do. Mỗi dự án gắn với hợp đồng và khách hàng.', 'project_contract R100'),
  ('acceptance', 'en', null, 'projects', 'Project acceptance and revenue', 'When a project is finished, finance, admins or executives accept the project. The project service calls the finance service to record the acceptance revenue, using the exchange rate of the acceptance date, and then marks the project as accepted. If the acceptance month is already closed, the acceptance is refused and the app shows why. Each project is linked to a contract and a customer.', 'project_contract R100'),
  ('access', 'vi', null, 'security', 'Ai được xem gì trong app', 'Nhân viên, HR, tài chính, quản trị và ban điều hành đều dùng được chấm công, phiếu lương của mình, dự án của tôi và kho tri thức. Hồ sơ nhân viên và danh sách dự án do ban điều hành, quản trị, HR và tài chính xem. Ứng viên do HR, quản trị và ban điều hành quản lý. Số liệu tài chính, báo cáo tập đoàn và chốt lương dành cho tài chính, quản trị và ban điều hành. Sổ kiểm toán do ban điều hành, quản trị và kiểm toán độc lập xem; tài khoản kiểm toán độc lập chỉ đọc và hết quyền sau ngày ghi trong hạn truy cập. Người ở nước này không đọc được dữ liệu của nước khác.', 'home_page.dart R88'),
  ('access', 'en', null, 'security', 'Who can see what in the app', 'Employees, HR, finance, admins and executives can all use attendance, their own payslips, my projects and the knowledge base. Employee records and the project list are viewed by executives, admins, HR and finance. Candidates are managed by HR, admins and executives. Finance figures, the group report and payroll closing are for finance, admins and executives. The audit log is viewed by executives, admins and the external auditor; the external auditor account is read-only and loses access after its access date. People in one country cannot read another country''s data.', 'home_page.dart R88'),
  ('knowledge-graph', 'vi', null, 'app', 'Đồ thị tri thức, suy luận và đề xuất từ AI', 'Đồ thị tri thức lưu kiến thức thành nút và cạnh có tên. Bản thể học định nghĩa các lớp và quy định mỗi quan hệ nối lớp nào với lớp nào. Máy suy luận dùng các luật để tự sinh cạnh mới, ví dụ quy trình có bước do một service xử lý thì quy trình có sự tham gia của service đó. AI đọc bài viết và đề xuất nút, cạnh mới kèm câu trích làm bằng chứng. Server kiểm đề xuất theo bản thể học trước khi lưu. HR, quản trị hoặc ban điều hành duyệt đề xuất; đề xuất được duyệt mới vào đồ thị và máy chạy lại suy luận.', 'ADR 0030'),
  ('knowledge-graph', 'en', null, 'app', 'Knowledge graph, reasoning and AI proposals', 'The knowledge graph stores knowledge as nodes and named edges. The ontology defines the classes and states which classes each relation may connect. The reasoner uses rules to derive new edges, for example a process whose step is handled by a service involves that service. The AI reads articles and proposes new nodes and edges with a quote as evidence. The server checks every proposal against the ontology before saving it. HR, admins or executives review the proposals; only approved proposals enter the graph, and then reasoning runs again.', 'ADR 0030')
